{"command":"cd /Users/dwahl/Scripts/pantoken && node --input-type=module <<'NODE'
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { listGuideFiles } from './tools/i18n-engine/src/extract.ts';
import { parsePo } from './tools/i18n-engine/src/po.ts';
import { normalizeWholeFileMarkdown } from './tools/i18n-engine/src/pipeline.ts';
const root = process.cwd();
const files = listGuideFiles(join(root, 'docs'));
const l10n = join(root, 'l10n');
for (const locale of readdirSync(l10n, { withFileTypes: true })) {
  if (!locale.isDirectory() || locale.name === 'en') continue;
  const poPath = join(l10n, locale.name, 'docs.guides.po');
  try {
    const entries = parsePo(readFileSync(poPath, 'utf8'));
    const translations = new Map(entries.filter(e => !e.obsolete).map(e => [e.msgid, e.msgstr]));
    let ok = true;
    for (const file of files) {
      const source = readFileSync(join(root, 'docs', file), 'utf8');
      const translated = translations.get(source) ?? '';
      const expected = normalizeWholeFileMarkdown(translated === '' ? source : translated) + '\n';
      const actual = readFileSync(join(root, 'docs', locale.name, file), 'utf8');
      if (expected !== actual) { console.log(locale.name, file); ok = false; break; }
    }
    if (ok && translations.size !== files.length) console.log(locale.name, 'po-count', translations.size, 'files', files.length);
  } catch (e) {
    console.log(locale.name, 'ERROR', e.message);
  }
}
